Actually let me verify CPython 3.13's exact algorithm. From compile.c:

```c
static int
compiler_enter_scope(struct compiler *c, identifier name,
                     int scope_type, void *key, int lineno,
                     Py_ssize_t firstlineno, int private)
{
    struct compiler_unit *u;

    u = compiler_new_unit(c);
    if (u == NULL) {
        return 0;
    }
    u->u_scope_type = scope_type;
    u->u_argcount = 0;
    u->u_lineno = lineno;
    u->u_col_offset = 0;
    u->u_end_lineno = 0;
    u->u_end_col_offset = 0;
    u->u_private = private;

    _Py_set_loc(c, name);

    /* Push the old compiler_unit on the stack. */
    if (c->u) {
        PyObject *capsule = PyCapsule_New(c->u, CAPSULE_NAME, NULL);
        if (!capsule || PyList_Append(c->c_stack, capsule) < 0) {
            Py_XDECREF(capsule);
            compiler_unit_free(u);
            return 0;
        }
        Py_DECREF(capsule);
    }
    c->u = u;

    c->c_nestlevel++;
    if (compiler_set_qualname(c, name) < 0) {
        return 0;
    }
    ...
}
